// XDATA: the story's data (EXPO_DATA, src/sets/data.js, generated by src/data/gen_data.py from the authors' deposit)
// decoded once, and the on-demand files in the package's data/ folder (targets.bin, ppi.bin, diseases.bin, names.json),
// fetched when a set or a pane first needs them. The app computes nothing scientific: every number the story shows is
// looked up here (src/SPEC.md, "The data"). Checked in Node by src/test-data.mjs.
// Substances are numbered 0 .. N-1: the network's NN nodes first, in the authors' VR order (row i of their layout), then
// the substances with genes but no link. Communities are numbered 0 .. comm.n-1: the 125 top ones, then the 152 middle,
// then the 456 fine (comm.lv tells which).
const XDATA = (() => {
  const D = typeof EXPO_DATA !== 'undefined' ? EXPO_DATA : require('./data.js');
  const bytes = s => (typeof atob === 'function' ? Uint8Array.from(atob(s), c => c.charCodeAt(0)) : new Uint8Array(Buffer.from(s, 'base64')));
  const TYPE = { B: Uint8Array, H: Uint16Array, h: Int16Array, I: Uint32Array };
  const arr = (t, buf, off, n) => {
    const T = TYPE[t], b = new Uint8Array(buf, off, n * T.BYTES_PER_ELEMENT);
    return new T(b.slice().buffer);   // (a copy: aligned, and its own)
  };
  const dec = k => { const [t, n, s] = D.b[k], b = bytes(s); return arr(t, b.buffer, b.byteOffset, n); };
  // a 0..65535 grid on [-lim, lim]
  const unq = (u, lim) => { const f = new Float32Array(u.length); for (let i = 0; i < u.length; i++) f[i] = (u[i] / 65535 * 2 - 1) * lim; return f; };
  const M = D.meta, N = M.nSubst, NN = M.nNet;
  const label = D.label.split('\n');
  const pos = unq(dec('pos'), 1), shelf = unq(dec('shelf'), 1);
  const cls = dec('cls'), prim = dec('prim'), fine = dec('fine'), pat = dec('pat'), hz = dec('haz');
  const ngenes = dec('ngenes'), nppi = dec('nppi'), maxdeg = dec('maxdeg'), deg = dec('deg'), near = dec('near'), close = dec('close');
  const links = dec('links'), lw8 = dec('lw'), lw = new Float32Array(lw8.length);
  for (let i = 0; i < lw8.length; i++) lw[i] = lw8[i] / 255;
  // communities: level, the authors' id ('11_2_1'), size, parent, the authors' colour, our plain label (or null), top terms
  const C = D.comm, CN = C.lv.length, CC = C.counts, base = [0, CC[0], CC[0] + CC[1]];
  const byLevel = [0, 1, 2].map(lv => Array.from({ length: CC[lv] }, (_, j) => base[lv] + j));
  const commId = new Map(C.id.map((id, k) => [C.lv[k] + ':' + id, k]));
  const comm = {
    n: CN, lv: C.lv, id: C.id, size: C.n, parent: C.parent, col: C.col, label: C.label, terms: C.terms, counts: CC, byLevel,
    find: (lv, id) => { const k = commId.get(lv + ':' + id); return k === undefined ? -1 : k; },
    // a community's words: its plain label, else its top enriched term, else ''
    words: k => C.label[k] || (C.terms[k] && C.terms[k][0]) || '',
  };
  // a substance's community at a level (0 top, 1 middle, 2 fine), or -1 (no link: not in the network)
  const commOf = (i, lv) => {
    if (fine[i] === 0xFFFF) return -1;
    let k = base[2] + fine[i];
    for (let l = 2; l > lv; l--) k = C.parent[k];
    return k;
  };
  const members = k => { const out = []; for (let i = 0; i < NN; i++) if (commOf(i, C.lv[k]) === k) out.push(i); return out; };
  // a pattern: 0 central module, 1 hubs, 2 module at the edge, 3 scattered, -1 none (not in the interactome)
  const pattern = i => (pat[i] === 255 ? -1 : pat[i]);
  const hazard = i => (hz[i] === 255 ? -1 : hz[i] / 100);
  const lower = label.map(s => s.toLowerCase());
  // substances whose label (or full name, once names.json is in) holds q, the best studied first, at most n
  const find = (q, n = 20) => {
    q = String(q || '').trim().toLowerCase();
    if (!q) return [];
    const out = [];
    for (let i = 0; i < N; i++) if (lower[i].includes(q) || (F.names && F.names.full[i] && F.names.full[i].toLowerCase().includes(q))) out.push(i);
    const rank = i => (lower[i] === q ? 0 : lower[i].startsWith(q) ? 1 : 2);
    return out.sort((a, b) => rank(a) - rank(b) || ngenes[b] - ngenes[a] || a - b).slice(0, n);
  };

  // ------------------------------------------------------------ the on-demand files (packages/exposome/data/)
  // Each .bin: 'XBN1', a u32 header length, a JSON header (its sections: name -> [type, offset, count(, lines)]) and the
  // sections, each 8-byte aligned after the header. A 'lines' section is UTF-8 text, one entry a line.
  const readBin = buf => {
    const u8 = new Uint8Array(buf), hl = new DataView(buf).getUint32(4, true);
    if (String.fromCharCode(...u8.subarray(0, 4)) !== 'XBN1') throw new Error('not an XBN1 file');
    const head = JSON.parse(new TextDecoder().decode(u8.subarray(8, 8 + hl))), at = 8 + hl, out = { head };
    for (const [k, [t, off, n]] of Object.entries(head.sections)) out[k] = t === 'lines' ? new TextDecoder().decode(u8.subarray(at + off, at + off + n)).split('\n') : arr(t, buf, at + off, n);
    return out;
  };
  const F = {};             // the files read: targets, ppi, diseases, names
  const P = {};             // their fetches under way
  const failed = new Set();
  const FILES = { targets: 'data/targets.bin', ppi: 'data/ppi.bin', diseases: 'data/diseases.bin', names: 'data/names.json' };
  const take = (name, raw) => {
    if (name === 'names') { const j = typeof raw === 'string' ? JSON.parse(raw) : raw; const full = new Array(N); for (const k in j.full) full[+k] = j.full[k]; F.names = { id: j.id, full }; return; }
    const R = readBin(raw);
    if (name === 'ppi') {
      const lim = R.head.lim;
      R.cellPos = unq(R.cell, lim); R.sortPos = unq(R.sorted, lim);
      R.bySym = new Map(R.sym.map((s, i) => [s, i]));
    }
    if (name === 'targets') R.bySym = new Map(R.sym.map((s, i) => [s, i]));
    if (name === 'diseases') {
      // the close pairs by disease too (they come by substance, then z)
      const nd = R.name.length, cnt = new Uint32Array(nd + 1);
      for (let j = 0; j < R.cd.length; j++) cnt[R.cd[j] + 1]++;
      for (let d = 0; d < nd; d++) cnt[d + 1] += cnt[d];
      const fill = cnt.slice(), byD = new Uint32Array(R.cd.length);
      for (let j = 0; j < R.cd.length; j++) byD[fill[R.cd[j]]++] = j;
      for (let d = 0; d < nd; d++) byD.subarray(cnt[d], cnt[d + 1]).sort((a, b) => R.cz[a] - R.cz[b] || a - b);
      const bySub = new Uint32Array(N + 1);
      for (let j = 0; j < R.cs.length; j++) bySub[R.cs[j] + 1]++;
      for (let s = 0; s < N; s++) bySub[s + 1] += bySub[s];
      Object.assign(R, { dOff: cnt, byD, sOff: bySub, byName: new Map(R.name.map((s, i) => [s, i])) });
    }
    F[name] = R;
  };
  // load(name): a promise of the file read (fetched once; url(file) gives its address: the package's pkgUrl)
  const load = (name, url) => {
    if (F[name]) return Promise.resolve(F[name]);
    if (P[name]) return P[name];
    if (typeof fetch === 'undefined' || !url) return Promise.reject(new Error('no fetch'));
    P[name] = fetch(url(FILES[name])).then(r => { if (!r.ok) throw new Error(FILES[name] + ': ' + r.status); return name === 'names' ? r.json() : r.arrayBuffer(); })
      .then(raw => { take(name, raw); return F[name]; })
      .catch(err => { failed.add(name); console.warn('exposome: ' + err.message); throw err; });
    return P[name];
  };
  // for a set's prep() or a load step: true once every named file is read (or has failed: the set then draws without it)
  const need = (names, url) => { let ok = true; for (const n of names) if (!F[n] && !failed.has(n)) { ok = false; load(n, url).catch(() => {}); } return ok; };
  const ready = name => !!F[name];

  // ------------------------------------------------------------ what the files give (each null until its file is read)
  // a substance's genes (indices into gene.sym, most studied first)
  const targets = i => (F.targets ? F.targets.gene.subarray(F.targets.off[i], F.targets.off[i + 1]) : null);
  // a substance's genes as interactome proteins (indices into ppi.sym; genes not in the interactome left out)
  const targetsPPI = i => {
    const t = targets(i);
    if (!t) return null;
    const g2p = F.targets.g2p, out = [];
    for (const g of t) if (g2p[g] !== 0xFFFF) out.push(g2p[g]);
    return Uint16Array.from(out);
  };
  // the substances that touch a gene (by symbol), most studied first: a scan of every substance (about 600,000 pairs)
  const subsOfGene = sym => {
    const g = F.targets && F.targets.bySym.get(sym);
    if (g === undefined) return null;
    const out = [], T = F.targets;
    for (let i = 0; i < N; i++) { const t = T.gene.subarray(T.off[i], T.off[i + 1]); if (t.includes(g)) out.push(i); }
    return out.sort((a, b) => ngenes[b] - ngenes[a] || a - b);
  };
  const dis = {
    get N() { return F.diseases ? F.diseases.name.length : 0; },
    name: d => (F.diseases ? F.diseases.name[d] : ''),
    find: s => (F.diseases && F.diseases.byName.has(s) ? F.diseases.byName.get(s) : -1),
    search: (q, n = 20) => { q = String(q || '').trim().toLowerCase(); if (!F.diseases || !q) return []; const out = []; F.diseases.name.forEach((s, d) => { if (s.toLowerCase().includes(q)) out.push(d); }); return out.sort((a, b) => F.diseases.near[b] - F.diseases.near[a] || a - b).slice(0, n); },
    // its genes as interactome proteins
    genes: d => (F.diseases ? F.diseases.gene.subarray(F.diseases.off[d], F.diseases.off[d + 1]) : null),
    // how many substances are significantly close (the 1,601,884 pairs, FDR < 0.05)
    near: d => (F.diseases ? F.diseases.near[d] : 0),
    // the closest pairs (z < -5: 176,259 in all), closest first: { s, d, z, cit } (cit: PubMed records naming both)
    closeOf: i => { const R = F.diseases; if (!R) return null; const out = []; for (let j = R.sOff[i]; j < R.sOff[i + 1]; j++) out.push({ s: i, d: R.cd[j], z: R.cz[j] / 100, cit: R.cc[j] }); return out; },
    closeTo: d => { const R = F.diseases; if (!R) return null; const out = []; for (let j = R.dOff[d]; j < R.dOff[d + 1]; j++) { const k = R.byD[j]; out.push({ s: R.cs[k], d, z: R.cz[k] / 100, cit: R.cc[k] }); } return out; },
  };
  const ppi = {
    get N() { return F.ppi ? F.ppi.sym.length : 0; },
    get head() { return F.ppi ? F.ppi.head : null; },
    sym: p => (F.ppi ? F.ppi.sym[p] : ''), find: s => (F.ppi && F.ppi.bySym.has(s) ? F.ppi.bySym.get(s) : -1),
    get deg() { return F.ppi && F.ppi.deg; }, get place() { return F.ppi && F.ppi.place; },
    get cell() { return F.ppi && F.ppi.cellPos; }, get sorted() { return F.ppi && F.ppi.sortPos; }, get links() { return F.ppi && F.ppi.links; },
    get places() { return F.ppi ? F.ppi.head.places : []; },
  };
  const gene = {
    get N() { return F.targets ? F.targets.sym.length : 0; },
    sym: g => (F.targets ? F.targets.sym[g] : ''), find: s => (F.targets && F.targets.bySym.has(s) ? F.targets.bySym.get(s) : -1),
    nsub: g => (F.targets ? F.targets.nsub[g] : 0), ppi: g => (F.targets && F.targets.g2p[g] !== 0xFFFF ? F.targets.g2p[g] : -1),
  };
  return {
    D, meta: M, ex: D.ex, N, NN, label, pos, shelf, cls, prim, fine, ngenes, nppi, maxdeg, deg, near, close, links, lw,
    comm, commOf, members, pattern, hazard, find, classes: M.classes, countries: D.countries,
    full: i => (F.names && F.names.full[i]) || label[i], id: i => (F.names ? F.names.id[i] : ''),
    FILES, load, need, ready, take, failed, targets, targetsPPI, subsOfGene, dis, ppi, gene,
  };
})();
if (typeof module !== 'undefined') module.exports = XDATA;
